def first_missing_positive(xs: list[int]) -> int:
    n = len(xs)
    if 1 not in xs:
        return 1

    # Replace negative numbers, zeros, and numbers larger than n with 1s
    for i in range(n):
        if xs[i] <= 0 or xs[i] > n:
            xs[i] = 1

    # Use index mapping to mark the presence of numbers
    for i in range(n):
        index = abs(xs[i]) - 1
        if xs[index] > 0:
            xs[index] = -xs[index]

    # Find the first cell which isn't negative (means its index + 1 is missing)
    for i in range(n):
