def add_big_digits(a: list[int], b: list[int]) -> list[int]:
    result = []
    carry = 0
    while a or b or carry:
        if a:
            carry += a.pop()
        if b:
            carry += b.pop()
        result.append(carry % 10)
        carry //= 10
    return result[::-1]
```

